"""Render the machine-readable EDA results as a Markdown data report."""

from __future__ import annotations

from typing import Any

HEADER = (
    "<!-- AUTO-GENERATED by `winemood data eda --publish`. Do not edit by hand; "
    "edit src/winemood/analysis/report.py and regenerate. -->"
)


def _pct(x: float) -> str:
    return f"{x * 100:.2f}%"


def _n(x: float) -> str:
    return f"{int(x):,}"


def _table(headers: list[str], rows: list[list[Any]]) -> str:
    out = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)


def _target_table(rep: dict[str, Any]) -> str:
    rows = [[k, _n(rep["support"][k]), _pct(rep["proportions"][k])] for k in rep["support"]]
    return _table(["Class", "Reviews", "Share"], rows)


def render(
    summary: dict[str, Any],
    model: dict[str, Any],
    manifests: dict[str, dict[str, Any]],
    figure_dir: str = "figures",
) -> str:
    v = summary["validation"]
    pts = summary["points"]
    lw = summary["length_words"]
    meta = summary["metadata"]
    t = meta.get("tasters", {})
    grouped = manifests.get("grouped_v1", {})
    taster = manifests.get("taster_holdout_v1", {})
    rho_tr = model["spearman_words_points_train"]
    targets = summary["targets"]
    fig = f"{figure_dir}/"

    parts: list[str] = [
        HEADER,
        "# WineMood: Data Report",
        f"Dataset SHA-256: `{grouped.get('dataset_sha256', 'n/a')}`. Every number in this "
        "file is produced by code (`src/winemood/analysis/`) from that exact file.",
        "Part I describes the whole corpus. Part II is computed on the **training split "
        "only** (plus a validation out-of-vocabulary diagnostic); the test split is not "
        "read. All associations are descriptive and carry no causal interpretation.",
        "## Part I: Descriptive statistics (whole corpus)",
        "### Integrity",
        _table(
            ["Check", "Value"],
            [
                ["Rows in raw file", _n(v["n_rows"])],
                ["Columns", len(v["columns"])],
                ["Missing / empty descriptions", f"{v['n_missing_text']} / {v['n_empty_text']}"],
                ["Descriptions with < 5 words", v["n_short_text"]],
                [
                    "Missing / non-integer / out-of-range points",
                    f"{v['n_missing_target']} / {v['n_non_integer_target']} / "
                    f"{v['n_out_of_range_target']}",
                ],
                ["Points range", f"{v['points_min']:.0f}-{v['points_max']:.0f}"],
                ["Exact duplicate descriptions", _n(v["n_duplicate_text"])],
                [
                    "Duplicates after case/whitespace normalisation",
                    _n(v["n_duplicate_text_normalized"]),
                ],
                ["Fully duplicated rows (all columns except id)", _n(v["n_duplicate_rows"])],
                ["Rows repeating an earlier `title`", _n(v["n_duplicate_title"])],
                ["Texts with control characters", v["n_texts_with_control_chars"]],
                ["Texts with U+FFFD replacement characters", v["n_texts_with_replacement_char"]],
                ["Texts with suspected mojibake", v["n_texts_with_suspected_mojibake"]],
                ["Texts containing non-ASCII characters", _n(v["n_texts_non_ascii"])],
            ],
        ),
        f"After exact deduplication (normalised text, lowest `review_id` kept): "
        f"**{_n(summary['n_rows_dedup'])} rows**. Distributions below use the deduplicated "
        "corpus.",
        f"![Missingness]({fig}missingness.png)",
        "### Critic scores",
        f"Mean {pts['mean']:.2f}, SD {pts['std']:.2f}, median {pts['p50']:.0f}, "
        f"range {pts['min']:.0f}-{pts['max']:.0f}. No review scores below 80, consistent with "
        "Wine Enthusiast's policy of not publishing wines under 80 points.",
        f"![Score distribution]({fig}score_distribution.png)",
        "### Candidate targets",
        "`we_category_v1` (published Wine Enthusiast categories):",
        _target_table(targets["we_category_v1"]),
        f"Imbalance ratio (largest / smallest class): "
        f"{targets['we_category_v1']['imbalance_ratio']:.1f}.",
        "`we_category_merged_v1` (Classic merged into Superb by the pre-declared rule):",
        _target_table(targets["we_category_merged_v1"]),
        f"Imbalance ratio: {targets['we_category_merged_v1']['imbalance_ratio']:.1f}.",
        "`points_binary_90_v1`:",
        _target_table(targets["points_binary_90_v1"]),
        "Legacy `points_band_v0` (deprecated; shown for the record):",
        _target_table(targets["points_band_v0"]),
        f"Empty classes in `points_band_v0`: {targets['points_band_v0']['empty_classes']}.",
        f"![Target distributions]({fig}target_distributions.png)",
        "### Review length",
        f"Words per review: mean {lw['mean']:.1f}, SD {lw['std']:.1f}, median {lw['p50']:.0f}, "
        f"5th-95th percentile {lw['p5']:.0f}-{lw['p95']:.0f}, max {lw['max']:.0f}. "
        f"Spearman correlation between length and points (whole corpus): "
        f"{summary['spearman_words_points_all']:.3f}.",
        _table(
            ["WE category", "Median words"],
            [[k, f"{m:.0f}"] for k, m in summary["median_words_by_we_category"].items()],
        ),
        f"![Length distribution]({fig}length_distribution.png)",
        "### Metadata and sampling",
        f"{meta.get('n_countries', 'n/a')} countries; the most frequent are: "
        + ", ".join(f"{k} ({_n(c)})" for k, c in list(meta.get("top_countries", {}).items())[:5])
        + ".",
        f"{meta.get('n_varieties', 'n/a')} varieties; the most frequent are: "
        + ", ".join(f"{k} ({_n(c)})" for k, c in list(meta.get("top_varieties", {}).items())[:5])
        + ".",
        f"Price: missing for {_n(meta['price']['missing'])} rows; median "
        f"{meta['price']['p50']:.0f}, 95th percentile {meta['price']['p95']:.0f}. Spearman "
        f"(price, points) = {meta['spearman_price_points']:.3f}."
        if "price" in meta
        else "",
        f"Tasters: {t.get('n_tasters')} named tasters; {_n(t.get('rows_missing_taster', 0))} "
        f"reviews have no taster. The largest taster wrote "
        f"{_pct(t.get('largest_taster_share', 0))} of all reviews. Mean score per taster "
        f"ranges from {t.get('mean_points_per_taster_min', 0):.2f} to "
        f"{t.get('mean_points_per_taster_max', 0):.2f}. Tasters are reported anonymously.",
        f"![Reviews per taster]({fig}taster_distribution.png)",
        f"Vintage (parsed from `title`): median {meta['vintage']['p50']:.0f}, "
        f"5th-95th percentile {meta['vintage']['p5']:.0f}-{meta['vintage']['p95']:.0f}; "
        f"not parseable for {_n(meta['vintage']['missing'])} titles."
        if "vintage" in meta
        else "",
        "## Split protocol results",
        _split_section(grouped, taster),
        "## Part II: Modelling-relevant analysis (training split only)",
        f"Training rows: {_n(model['n_train'])}. Vocabulary (lower-cased word tokens): "
        f"{_n(model['vocabulary_size'])} types, {_n(model['terms_with_count_ge_5'])} occurring "
        "at least 5 times.",
        _table(
            ["Top-k training terms", "Training tokens covered", "Validation OOV rate"],
            [
                [
                    _n(int(k)),
                    _pct(c),
                    _pct(model["validation_oov_rate_by_vocab_size"][k])
                    if k in model["validation_oov_rate_by_vocab_size"]
                    else "",
                ]
                for k, c in model["token_coverage_by_top_k"].items()
            ],
        ),
        f"![Vocabulary coverage]({fig}vocabulary_coverage_train.png)",
        f"Length vs points (training split): Spearman rho = {rho_tr['rho']:.3f} "
        f"(95% bootstrap CI {rho_tr['ci95_low']:.3f} to {rho_tr['ci95_high']:.3f}, "
        f"n = {_n(rho_tr['n'])}). Length is therefore a strong candidate shortcut, so the "
        "experimental protocol requires a length-only baseline.",
        _table(
            ["Length decile (words)", "Mean points", "Reviews"],
            [
                [d["bin"], f"{d['mean_points']:.2f}", _n(d["n"])]
                for d in model["mean_points_by_length_decile"]
            ],
        ),
        f"![Length vs score]({fig}length_vs_score_train.png)",
        "Most frequent n-grams (English stop words removed):",
        _table(
            ["Unigram", "Count", "Bigram", "Count", "Trigram", "Count"],
            [
                [*model["top_unigrams"][i], *model["top_bigrams"][i], *model["top_trigrams"][i]]
                for i in range(
                    min(
                        15,
                        len(model["top_unigrams"]),
                        len(model["top_bigrams"]),
                        len(model["top_trigrams"]),
                    )
                )
            ],
        ),
        "Terms most associated with >= 90 versus < 90 points (weighted log-odds with an "
        "informative Dirichlet prior; Monroe, Colaresi & Quinn, 2008). These are "
        "associations in the training data, not evidence of what makes a wine good.",
        _table(
            ["Favours >= 90", "z", "Favours < 90", "z"],
            [
                [a[0], f"{a[1]:.1f}", b[0], f"{b[1]:.1f}"]
                for a, b in zip(
                    model["log_odds_ge90_vs_lt90"]["favours_a"][:15],
                    model["log_odds_ge90_vs_lt90"]["favours_b"][:15],
                    strict=False,
                )
            ],
        ),
        f"![Log-odds terms]({fig}log_odds_terms_train.png)",
        "### Merge rule check",
        f"Re-deriving the pre-declared merge rule (min class share "
        f"{_pct(model['merge_rule']['min_class_fraction'])}) on the training split gives "
        f"classes {model['merge_rule']['classes']}; matches the frozen "
        f"`we_category_merged_v1`: **{model['merge_rule']['matches_frozen_scheme']}**.",
    ]
    return "\n\n".join(p for p in parts if p) + "\n"


def _split_section(grouped: dict[str, Any], taster: dict[str, Any]) -> str:
    if not grouped:
        return "_Split manifests not available._"
    g = grouped["groups"]
    d = grouped["dedup"]
    total = sum(grouped["counts"].values())
    lines = [
        f"Exact deduplication removed {_n(d['n_removed'])} rows "
        f"({_n(d['n_duplicate_groups'])} duplicate groups; "
        f"{d['n_groups_with_conflicting_scores']} groups whose copies carry different scores).",
        f"Near-duplicates (MinHash/LSH, verified word-3-gram Jaccard >= threshold): "
        f"{g['n_near_dup_pairs']} pairs covering {g['n_rows_in_near_dup_clusters']} rows. "
        f"{_n(g['n_rows_sharing_title'])} rows share a `title` (same wine and vintage) with "
        f"another row. Union of these links: {_n(g['n_groups'])} groups, "
        f"{_n(g['n_multi_row_groups'])} with more than one row (largest: {g['largest_group']}).",
        _table(
            ["Split (grouped_v1)", "Rows", "Share", "ID fingerprint (SHA-256, first 16)"],
            [
                [p, _n(c), _pct(c / total), f"`{grouped['id_sha256'][p][:16]}`"]
                for p, c in grouped["counts"].items()
            ],
        ),
    ]
    if taster:
        lines.append(
            _table(
                ["Split (taster_holdout_v1)", "Rows"],
                [[p, _n(c)] for p, c in taster["counts"].items()],
            )
        )
    return "\n\n".join(lines)
